js:function(context, args) {
  var actor = args && args.actor;
  if (typeof actor !== 'string' || actor.length === 0) {
    return {defer: 'missing current arguments', parameters: 'actor (string): the experiment actor whose entries should be appended and summarized'};
  }
  var hist = Array.isArray(context && context.history) ? context.history : [];
  var appends = 0;
  var summary = null;
  for (var i = 0; i < hist.length; i++) {
    var h = hist[i];
    var argv = h && h.decoded_argv;
    if (!argv || argv[0] !== 'experiment' || argv[2] !== actor) continue;
    if (argv[1] === 'append') appends += 1;
    else if (argv[1] === 'summary') summary = h;
  }
  for (var k = appends; k < 2; k++) {
    var r = execute({name: 'bash', arguments: {command: command('experiment', ['append', actor])}, read: false, step: 'append', occurrence: k});
    if (r && r.is_error) return {defer: 'append dispatch failed for actor ' + actor};
  }
  if (!summary) {
    execute({name: 'bash', arguments: {command: command('experiment', ['summary', actor])}, read: true});
  }
  if (!summary) {
    for (var j = 0; j < hist.length; j++) {
      var hj = hist[j];
      var av = hj && hj.decoded_argv;
      if (av && av[0] === 'experiment' && av[1] === 'summary' && av[2] === actor) summary = hj;
    }
  }
  if (!summary) return {defer: 'no summary evidence for actor ' + actor};
  var sd = summary.data || {};
  return {report: {actor: actor, count: sd.count, complete: sd.complete, receipt: sd.receipt}};
}
